    """
    Implements a recursive backtracking algorithm to match a given text against a pattern
    supporting literal characters, '.', '*', and '+'. 
    """

    def is_match(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern) and t_index == len(text):
